import { CodeBlock } from "@/registry/erbium/blocks/code-block";
import { Form, useAppForm } from "@/registry/erbium/ui/form";

const CheckboxForm = () => {
  const form = useAppForm({
    defaultValues: { newsletter: false, terms: false },
  });

  return (
    <Form form={form} className="flex w-72 flex-col gap-group">
      <form.AppField
        name="terms"
        validators={{
          onDynamic: ({ value }) => (value ? undefined : "Accept the terms to continue."),
        }}
      >
        {(field) => <field.CheckboxField label="Accept terms and conditions" required showError />}
      </form.AppField>
      <form.AppField name="newsletter">
        {(field) => <field.CheckboxField label="Subscribe to the newsletter" />}
      </form.AppField>
      <form.SubmitButton className="self-start">Submit</form.SubmitButton>
      <form.Subscribe
        selector={(state) =>
          state.isSubmitSuccessful && !state.isSubmitting ? state.values : undefined
        }
      >
        {(values) =>
          values && (
            <CodeBlock
              code={JSON.stringify(values, null, 2)}
              language="json"
              title="Submitted values"
            />
          )
        }
      </form.Subscribe>
    </Form>
  );
};

export default CheckboxForm;

import { Checkbox, CheckboxGroup } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { useState } from "react";

const permissions = [
  { id: "read", label: "Read" },
  { id: "write", label: "Write" },
  { id: "delete", label: "Delete" },
];

const CheckboxIndeterminate = () => {
  const [selected, setSelected] = useState<string[]>(["read"]);

  return (
    <CheckboxGroup
      aria-labelledby="permissions-all-label"
      allValues={permissions.map((permission) => permission.id)}
      value={selected}
      onValueChange={setSelected}
    >
      <Field orientation="horizontal">
        <Checkbox id="permissions-all" parent />
        <FieldLabel id="permissions-all-label" htmlFor="permissions-all">
          All permissions
        </FieldLabel>
      </Field>
      {permissions.map((permission) => (
        <Field orientation="horizontal" className="ps-6" key={permission.id}>
          <Checkbox id={`permissions-${permission.id}`} value={permission.id} />
          <FieldLabel className="font-normal" htmlFor={`permissions-${permission.id}`}>
            {permission.label}
          </FieldLabel>
        </Field>
      ))}
    </CheckboxGroup>
  );
};

export default CheckboxIndeterminate;

