import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { useDragSelect } from "@/registry/erbium/hooks/use-drag-select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/registry/erbium/ui/table";
import {
  createColumnHelper,
  metaHelper,
  rowSelectionFeature,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
}

const tableData: User[] = [
  { email: "sarah.chen@example.com", id: "1", name: "Sarah Chen", role: "Admin" },
  { email: "marcus.rodriguez@example.com", id: "2", name: "Marcus Rodriguez", role: "User" },
  { email: "priya.patel@example.com", id: "3", name: "Priya Patel", role: "User" },
  { email: "david.kim@example.com", id: "4", name: "David Kim", role: "Editor" },
];

const features = tableFeatures({
  columnMeta: metaHelper<{ selection?: boolean }>(),
  rowSelectionFeature,
});

const columnHelper = createColumnHelper<typeof features, User>();

const columns = columnHelper.columns([
  columnHelper.display({
    cell: ({ row }) => (
      <Checkbox
        aria-label={`Select ${row.original.name}`}
        checked={row.getIsSelected()}
        disabled={!row.getCanSelect()}
        onCheckedChange={(checked) => {
          row.toggleSelected(checked);
        }}
      />
    ),
    header: ({ table }) => (
      <Checkbox
        aria-label="Select all rows"
        checked={table.getIsAllRowsSelected()}
        // v9's getIsSomeRowsSelected() is also true when every row is selected.
        indeterminate={table.getIsSomeRowsSelected() && !table.getIsAllRowsSelected()}
        onCheckedChange={(checked) => {
          table.toggleAllRowsSelected(checked);
        }}
      />
    ),
    id: "select",
    meta: { selection: true },
  }),
  columnHelper.accessor("name", {
    cell: (info) => <span className="font-medium">{info.getValue()}</span>,
    header: "Name",
  }),
  columnHelper.accessor("email", { header: "Email" }),
  columnHelper.accessor("role", { header: "Role" }),
]);

export const CheckboxInTable = () => {
  const table = useTable({
    columns,
    data: tableData,
    features,
    getRowId: (row) => row.id,
    initialState: { rowSelection: { "1": true } },
  });

  const { rows } = table.getRowModel();

  const dragSelect = useDragSelect({
    resolve(target) {
      const index = target.closest("tr")?.sectionRowIndex ?? -1;
      const row = rows[index];

      return row?.getCanSelect() ? { index, selected: row.getIsSelected() } : null;
    },
    selectRange(start, end, selected) {
      for (const row of rows.slice(start, end + 1)) {
        if (row.getCanSelect()) {
          row.toggleSelected(selected);
        }
      }
    },
  });

  return (
    <Table>
      <TableHeader>
        {table.getHeaderGroups().map((headerGroup) => (
          <TableRow key={headerGroup.id}>
            {headerGroup.headers.map((header) => (
              <TableHead
                className={header.column.columnDef.meta?.selection ? "w-8" : undefined}
                key={header.id}
              >
                {header.isPlaceholder ? null : <table.FlexRender header={header} />}
              </TableHead>
            ))}
          </TableRow>
        ))}
      </TableHeader>
      <TableBody {...dragSelect}>
        {rows.map((row) => (
          <TableRow data-state={row.getIsSelected() ? "selected" : undefined} key={row.id}>
            {row.getAllCells().map((cell) => (
              <TableCell
                className={cell.column.columnDef.meta?.selection ? "w-8" : undefined}
                key={cell.id}
              >
                <table.FlexRender cell={cell} />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
};

